-- name: by_schema
-- dialect: teradata
LOCKING ROW FOR ACCESS
WITH primary_cols AS (SELECT DISTINCT UPPER(TRIM(DatabaseName)) AS db_name, UPPER(TRIM(TableName)) AS tbl_name, UPPER(TRIM(ColumnName)) AS col_name FROM DBC.IndicesV WHERE TRIM(IndexType) IN ('K', 'P', 'Q') AND TRIM(UniqueFlag) = 'Y'), unique_single_cols AS (SELECT UPPER(TRIM(DatabaseName)) AS db_name, UPPER(TRIM(TableName)) AS tbl_name, MAX(UPPER(TRIM(ColumnName))) AS col_name FROM DBC.IndicesV WHERE TRIM(UniqueFlag) = 'Y' GROUP BY UPPER(TRIM(DatabaseName)), UPPER(TRIM(TableName)), IndexNumber HAVING COUNT(*) = 1)
SELECT TRIM(c.DatabaseName) AS schema_name, TRIM(c.TableName) AS table_name, TRIM(c.ColumnName) AS column_name, CASE TRIM(c.ColumnType) WHEN 'CV' THEN 'VARCHAR' WHEN 'CF' THEN 'CHAR' WHEN 'CO' THEN 'CLOB' WHEN 'I' THEN 'INTEGER' WHEN 'I1' THEN 'BYTEINT' WHEN 'I2' THEN 'SMALLINT' WHEN 'I8' THEN 'BIGINT' WHEN 'D' THEN 'DECIMAL' WHEN 'N' THEN 'NUMBER' WHEN 'F' THEN 'DOUBLE PRECISION' WHEN 'DA' THEN 'DATE' WHEN 'AT' THEN 'TIME' WHEN 'TS' THEN 'TIMESTAMP' WHEN 'TZ' THEN 'TIME WITH TIME ZONE' WHEN 'SZ' THEN 'TIMESTAMP WITH TIME ZONE' WHEN 'BV' THEN 'VARBYTE' WHEN 'BF' THEN 'BYTE' WHEN 'BO' THEN 'BLOB' WHEN 'JN' THEN 'JSON' WHEN 'XM' THEN 'XML' WHEN 'PD' THEN 'PERIOD(DATE)' WHEN 'PT' THEN 'PERIOD(TIME)' WHEN 'PZ' THEN 'PERIOD(TIME WITH TIME ZONE)' WHEN 'PS' THEN 'PERIOD(TIMESTAMP)' WHEN 'PM' THEN 'PERIOD(TIMESTAMP WITH TIME ZONE)' WHEN 'UT' THEN COALESCE(NULLIF(TRIM(c.ColumnUDTName), ''), 'UDT') ELSE NULLIF(TRIM(c.ColumnType), '') END AS data_type, NULLIF(TRIM(c.ColumnType), '') AS raw_column_type, CASE WHEN TRIM(c.Nullable) = 'N' THEN 0 ELSE 1 END AS is_nullable, c.DefaultValue AS column_default, ROW_NUMBER() OVER (PARTITION BY UPPER(TRIM(c.DatabaseName)), UPPER(TRIM(c.TableName)) ORDER BY c.ColumnId) AS ordinal_position,
CASE WHEN TRIM(c.ColumnType) IN ('CV', 'CF', 'CO', 'BV', 'BF', 'BO', 'JN', 'XM') THEN CASE WHEN c.CharType = 2 AND c.ColumnLength IS NOT NULL AND TRIM(c.ColumnType) IN ('CV', 'CF') THEN CAST(c.ColumnLength / 2 AS INTEGER) ELSE c.ColumnLength END ELSE NULL END AS max_length,
c.DecimalTotalDigits AS numeric_precision, c.DecimalFractionalDigits AS numeric_scale, CASE WHEN p.col_name IS NOT NULL THEN 1 ELSE 0 END AS is_primary, CASE WHEN u.col_name IS NOT NULL THEN 1 ELSE 0 END AS is_unique, CASE WHEN TRIM(c.IdColType) IN ('GA', 'GD') THEN 1 ELSE 0 END AS is_identity, CASE TRIM(c.IdColType) WHEN 'GA' THEN 'ALWAYS' WHEN 'GD' THEN 'BY DEFAULT' ELSE NULL END AS identity_generation, 0 AS is_generated, c.CommentString AS column_comment
FROM DBC.ColumnsV c JOIN DBC.TablesV t ON UPPER(TRIM(c.DatabaseName)) = UPPER(TRIM(t.DatabaseName)) AND UPPER(TRIM(c.TableName)) = UPPER(TRIM(t.TableName)) LEFT JOIN primary_cols p ON p.db_name = UPPER(TRIM(c.DatabaseName)) AND p.tbl_name = UPPER(TRIM(c.TableName)) AND p.col_name = UPPER(TRIM(c.ColumnName)) LEFT JOIN unique_single_cols u ON u.db_name = UPPER(TRIM(c.DatabaseName)) AND u.tbl_name = UPPER(TRIM(c.TableName)) AND u.col_name = UPPER(TRIM(c.ColumnName)) WHERE UPPER(TRIM(c.DatabaseName)) = UPPER(TRIM(COALESCE(:schema_name, DATABASE))) AND UPPER(TRIM(c.DatabaseName)) NOT IN ('DBC', 'SYSUDTLIB', 'SYSLIB', 'TD_SYSFNLIB', 'SYSSPATIAL', 'SYSBAR', 'LOCKLOGSHREDDER', 'SQLJ', 'TDSTATS', 'TD_SERVER_DB', 'CRASHDUMPS') AND TRIM(t.TableKind) IN ('T', 'O', 'V')  ORDER BY TRIM(c.DatabaseName), TRIM(c.TableName), c.ColumnId;

-- name: by_table
-- dialect: teradata
LOCKING ROW FOR ACCESS
WITH primary_cols AS (SELECT DISTINCT UPPER(TRIM(DatabaseName)) AS db_name, UPPER(TRIM(TableName)) AS tbl_name, UPPER(TRIM(ColumnName)) AS col_name FROM DBC.IndicesV WHERE TRIM(IndexType) IN ('K', 'P', 'Q') AND TRIM(UniqueFlag) = 'Y'), unique_single_cols AS (SELECT UPPER(TRIM(DatabaseName)) AS db_name, UPPER(TRIM(TableName)) AS tbl_name, MAX(UPPER(TRIM(ColumnName))) AS col_name FROM DBC.IndicesV WHERE TRIM(UniqueFlag) = 'Y' GROUP BY UPPER(TRIM(DatabaseName)), UPPER(TRIM(TableName)), IndexNumber HAVING COUNT(*) = 1)
SELECT TRIM(c.DatabaseName) AS schema_name, TRIM(c.TableName) AS table_name, TRIM(c.ColumnName) AS column_name, CASE TRIM(c.ColumnType) WHEN 'CV' THEN 'VARCHAR' WHEN 'CF' THEN 'CHAR' WHEN 'CO' THEN 'CLOB' WHEN 'I' THEN 'INTEGER' WHEN 'I1' THEN 'BYTEINT' WHEN 'I2' THEN 'SMALLINT' WHEN 'I8' THEN 'BIGINT' WHEN 'D' THEN 'DECIMAL' WHEN 'N' THEN 'NUMBER' WHEN 'F' THEN 'DOUBLE PRECISION' WHEN 'DA' THEN 'DATE' WHEN 'AT' THEN 'TIME' WHEN 'TS' THEN 'TIMESTAMP' WHEN 'TZ' THEN 'TIME WITH TIME ZONE' WHEN 'SZ' THEN 'TIMESTAMP WITH TIME ZONE' WHEN 'BV' THEN 'VARBYTE' WHEN 'BF' THEN 'BYTE' WHEN 'BO' THEN 'BLOB' WHEN 'JN' THEN 'JSON' WHEN 'XM' THEN 'XML' WHEN 'PD' THEN 'PERIOD(DATE)' WHEN 'PT' THEN 'PERIOD(TIME)' WHEN 'PZ' THEN 'PERIOD(TIME WITH TIME ZONE)' WHEN 'PS' THEN 'PERIOD(TIMESTAMP)' WHEN 'PM' THEN 'PERIOD(TIMESTAMP WITH TIME ZONE)' WHEN 'UT' THEN COALESCE(NULLIF(TRIM(c.ColumnUDTName), ''), 'UDT') ELSE NULLIF(TRIM(c.ColumnType), '') END AS data_type, NULLIF(TRIM(c.ColumnType), '') AS raw_column_type, CASE WHEN TRIM(c.Nullable) = 'N' THEN 0 ELSE 1 END AS is_nullable, c.DefaultValue AS column_default, ROW_NUMBER() OVER (PARTITION BY UPPER(TRIM(c.DatabaseName)), UPPER(TRIM(c.TableName)) ORDER BY c.ColumnId) AS ordinal_position,
CASE WHEN TRIM(c.ColumnType) IN ('CV', 'CF', 'CO', 'BV', 'BF', 'BO', 'JN', 'XM') THEN CASE WHEN c.CharType = 2 AND c.ColumnLength IS NOT NULL AND TRIM(c.ColumnType) IN ('CV', 'CF') THEN CAST(c.ColumnLength / 2 AS INTEGER) ELSE c.ColumnLength END ELSE NULL END AS max_length,
c.DecimalTotalDigits AS numeric_precision, c.DecimalFractionalDigits AS numeric_scale, CASE WHEN p.col_name IS NOT NULL THEN 1 ELSE 0 END AS is_primary, CASE WHEN u.col_name IS NOT NULL THEN 1 ELSE 0 END AS is_unique, CASE WHEN TRIM(c.IdColType) IN ('GA', 'GD') THEN 1 ELSE 0 END AS is_identity, CASE TRIM(c.IdColType) WHEN 'GA' THEN 'ALWAYS' WHEN 'GD' THEN 'BY DEFAULT' ELSE NULL END AS identity_generation, 0 AS is_generated, c.CommentString AS column_comment
FROM DBC.ColumnsV c JOIN DBC.TablesV t ON UPPER(TRIM(c.DatabaseName)) = UPPER(TRIM(t.DatabaseName)) AND UPPER(TRIM(c.TableName)) = UPPER(TRIM(t.TableName)) LEFT JOIN primary_cols p ON p.db_name = UPPER(TRIM(c.DatabaseName)) AND p.tbl_name = UPPER(TRIM(c.TableName)) AND p.col_name = UPPER(TRIM(c.ColumnName)) LEFT JOIN unique_single_cols u ON u.db_name = UPPER(TRIM(c.DatabaseName)) AND u.tbl_name = UPPER(TRIM(c.TableName)) AND u.col_name = UPPER(TRIM(c.ColumnName)) WHERE UPPER(TRIM(c.DatabaseName)) = UPPER(TRIM(COALESCE(:schema_name, DATABASE))) AND UPPER(TRIM(c.DatabaseName)) NOT IN ('DBC', 'SYSUDTLIB', 'SYSLIB', 'TD_SYSFNLIB', 'SYSSPATIAL', 'SYSBAR', 'LOCKLOGSHREDDER', 'SQLJ', 'TDSTATS', 'TD_SERVER_DB', 'CRASHDUMPS') AND TRIM(t.TableKind) IN ('T', 'O', 'V')  AND UPPER(TRIM(c.TableName)) = UPPER(TRIM(:table_name)) ORDER BY TRIM(c.DatabaseName), TRIM(c.TableName), c.ColumnId;
